from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            suffix = match_value[2:]
            # Must be a strict subdomain, not the domain itself.
            return host.endswith("." + suffix) and host != suffix

        return host == match_value

    def replace_host(parts, new_host):
        netloc = parts.netloc

        # Preserve user information, if present.
        userinfo = ""
        if "@" in netloc:
            userinfo, netloc = netloc.rsplit("@", 1)
            userinfo += "@"

        # Preserve the original port.
        port_suffix = ""
        if netloc.startswith("["):
            closing_bracket = netloc.find("]")
            if closing_bracket != -1:
                port_suffix = netloc[closing_bracket + 1:]
        elif ":" in netloc:
            port_suffix = ":" + netloc.rsplit(":", 1)[1]

        # Bracket an IPv6 replacement host if necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        return parts._replace(
            netloc=userinfo + new_host + port_suffix
        )

    result = []

    for url in urls:
        parts = urlsplit(url)
        rewritten_url = url
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            applies = False

            if match_type == "path_prefix":
                applies = parts.path.startswith(match_value)

            elif match_type == "host":
                applies = host_matches(parts.hostname, match_value)

            elif match_type == "query_param":
                parameter_names = {
                    name for name, _ in parse_qsl(
                        parts.query,
                        keep_blank_values=True
                    )
                }
                applies = match_value in parameter_names

            if not applies:
                continue

            matched = True

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                new_path = parts.path

                if new_path.startswith(prefix):
                    new_path = new_path[len(prefix):]

                if not new_path:
                    new_path = "/"

                rewritten_url = urlunsplit(parts._replace(path=new_path))

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    replace_host(parts, rule["action_value"])
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                new_query = (
                    addition
                    if not parts.query
                    else parts.query + "&" + addition
                )
                rewritten_url = urlunsplit(
                    parts._replace(query=new_query)
                )

            # Only the first matching rule is applied.
            break

        result.append(rewritten_url if matched else url)

    return result
